def submit_training_job(
    server: str,
    gpu_ids: list[str],
    command: str,
    exp_id: str,
    timeout_hours: float = 24.0,
    work_dir: str | None = None,
    *,
    account: str | None = None,
    project: str | None = None,
) -> ToolResult:
    """Submit a training job to a remote GPU server.

    Validates requested GPUs against resources.yaml (including collision detection
    with running experiments), then launches the command in a detached tmux
    session named after the exp_id. Captures the PID and returns it for monitoring.

    Args:
        server: Server name from resources.yaml.
        gpu_ids: List of CUDA device ids (e.g. ["cuda:0", "cuda:1"]).
        command: Training command to execute.
        exp_id: Experiment identifier (used as tmux session name).
        timeout_hours: Max runtime before auto-kill (default 24h).
        work_dir: Working directory on the remote server. Falls back to
            project_path, then the account's ``work_dir``, then ``~``.
        account: SSH account (user) on the server. None = default account.
        project: Project name for access control and directory isolation.

    Returns:
        ToolResult with pid and session info.
    """
    t0 = time.monotonic()

    # Validate inputs against shell injection
    try:
        exp_id = _validate_identifier(exp_id, "exp_id")
    except ValueError as e:
        return ToolResult(success=False, error=str(e), metadata={"elapsed_seconds": 0})

    # --- Project-Server access control ---
    if project:
        try:
            from core.tools.project_config import load_project_config
            cfg_result = load_project_config(project)
            if cfg_result.success:
                exec_cfg = cfg_result.data.get("config", {}).get("execution", {})
                allowed_server = exec_cfg.get("server")
                allowed_account = exec_cfg.get("account")
                if allowed_server and server != allowed_server:
                    logger.debug("Access REJECTED: project=%s server=%s != allowed=%s", project, server, allowed_server)
                    return ToolResult(
                        success=False,
                        error=f"Project '{project}' is bound to server '{allowed_server}', not '{server}'. "
                              f"Update config/projects/{project}.yaml to change the binding.",
                        metadata={"elapsed_seconds": 0},
                    )
                if allowed_account and account and account != allowed_account:
                    logger.debug("Access REJECTED: project=%s account=%s != allowed=%s", project, account, allowed_account)
                    return ToolResult(
                        success=False,
                        error=f"Project '{project}' is bound to account '{allowed_account}', not '{account}'.",
                        metadata={"elapsed_seconds": 0},
                    )
                # Auto-fill account from project config if not specified
                if not account and allowed_account:
                    account = allowed_account
                # Warn if server has multiple accounts but project has no binding
                if not allowed_account and not account:
                    try:
                        srv_accounts = get_server_accounts(server)
                        if len(srv_accounts) > 1:
                            logger.warning(
                                "Project '%s' has no account binding but server '%s' has %d accounts; "
                                "defaulting to '%s'. Set execution.account in project config to be explicit.",
                                project, server, len(srv_accounts), srv_accounts[0]["user"],
                            )
                    except Exception:
                        pass  # server accounts lookup is best-effort
                logger.debug("Access ACCEPTED: project=%s server=%s account=%s", project, server, account)
        except Exception as e:
            logger.warning("Failed to load project config for access control (project=%s): %s", project, e)
            return ToolResult(
                success=False,
                error=f"Cannot verify access control for project '{project}': {e}",
                metadata={"elapsed_seconds": 0},
            )

    # Validate GPUs (with collision detection)
    # Note: exclude the current experiment from occupied check — when called
    # from submit_on_allocated, the experiment is already ALLOCATED with these
    # GPUs, so it would otherwise block itself.
    try:
        from core.tools.gpu_allocator import get_truly_available_gpus, get_occupied_gpus, invalidate_gpu_cache
        invalidate_gpu_cache()
        occupied = get_occupied_gpus()
        # Build available list excluding self from occupied
        config_available = set(_get_available_gpu_ids(server))
        occupied_by_others = {
            gpu_id for (srv, gpu_id), (eid, _) in occupied.items()
            if srv == server and eid != exp_id
        }
        available = sorted(config_available - occupied_by_others)
    except ImportError:
        available = _get_available_gpu_ids(server)
        occupied = {}

    for gid in gpu_ids:
        if gid not in available:
            occupant = occupied.get((server, gid))
            if occupant and occupant[0] != exp_id:
                return ToolResult(
                    success=False,
                    error=f"GPU {gid} is occupied by experiment '{occupant[0]}' (project: {occupant[1]}). Available: {available}",
                    metadata={"elapsed_seconds": 0},
                )
            return ToolResult(
                success=False,
                error=f"GPU {gid} is not available. Available: {available}",
                metadata={"elapsed_seconds": 0},
            )

        )

# Resolve work_dir: explicit > project_path > account > server > ~
resolved = _resolve_account(server, account)
resources = _load_resources()
srv_cfg = resources.get("servers", {}).get(server, {})
project_work_dir = _resolve_project_work_dir(project, server, account)
resolved_work_dir = work_dir or project_work_dir or resolved.work_dir or srv_cfg.get("work_dir", "~")
if resolved_work_dir in ("~", "") and project:
    return ToolResult(
        success=False,
        error=(
            f"work_dir resolved to '{resolved_work_dir}' for project '{project}'. "
            f"Set execution.project_path in the project config "
            f"(via update_project_config) to specify the remote working directory."
        ),
        metadata={"elapsed_seconds": 0},
    )
# env_activate priority: account > server > project config
env_activate = resolved.env_activate or srv_cfg.get("env_activate", "")
if not env_activate and project:
    try:
        from core.tools.project_config import load_project_config
        cfg_result = load_project_config(project)
        if cfg_result.success:
            env_activate = cfg_result.data.get("config", {}).get("execution", {}).get("env_activate", "")
    except Exception:
        pass
# Validate work_dir
try:
    _validate_path(resolved_work_dir, "work_dir")
except ValueError as e:
    return ToolResult(success=False, error=str(e), metadata={"elapsed_seconds": 0})

# Resolve execution backend (tmux or slurm) from server config
from core.tools.execution_backends import get_execution_backend, get_backend_name
backend = get_execution_backend(server, srv_cfg)
backend_name = get_backend_name(server, srv_cfg)

# Slurm runs under bash natively; bash-wrapper check only applies to tmux
if backend_name == "tmux":
    _wrap_err = _check_bash_wrapper(command)
    if _wrap_err:
        return ToolResult(
            success=False,
            error=_wrap_err,
            metadata={"elapsed_seconds": 0, "validator": "bash_wrapper"},
        )

log_file = _resolve_project_log_dir(project, exp_id)
log_dir = "/".join(log_file.rsplit("/", 1)[:-1])
timeout_secs = int(timeout_hours * 3600)
cvd = ",".join(g.split(":", 1)[1] if ":" in g else g for g in gpu_ids)

# Inject W&B API key if configured (encrypted file > env var)
wandb_key = ""
try:
    from core.crypto import load_secret
    from core import paths as _paths_mod
    wandb_key = load_secret(_paths_mod.config_dir() / "wandb_api_key.enc") or ""
except Exception:
    pass
if not wandb_key:
    wandb_key = os.environ.get("WANDB_API_KEY", "")

sentinel_dir = "/tmp/agent-ml-exit"
if backend_name == "slurm":
    slurm_cfg = srv_cfg.get("slurm", {})
    sentinel_dir = slurm_cfg.get("sentinel_dir", "~/.agent-ml-exit")

try:
    conn = _get_connection(server, account)
    submit_result = backend.submit_job(
        conn,
        exp_id=exp_id,
        command=command,
        gpu_ids=gpu_ids,
        work_dir=resolved_work_dir,
        log_file=log_file,
        log_dir=log_dir,
        env_activate=env_activate,
        timeout_secs=timeout_secs,
        wandb_key=wandb_key,
        cvd=cvd,
        sentinel_dir=sentinel_dir,
    )

    if not submit_result.success:
        return ToolResult(
            success=False,
            error=submit_result.error,
            metadata={"elapsed_seconds": round(time.monotonic() - t0, 2)},
        )

    pid = submit_result.job_handle

    # Auto-collect provenance spec into registry
    try:
        from core.tools.registry import update_registry as _update_registry
        auto_spec = {
